  "answer": "const fs = require('fs');

const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const arr = input.slice(1, n + 1);

let current = arr[0];
let maxSum = arr[0];

for (let i = 1; i < n; i++) {
  current = Math.max(arr[i], current + arr[i]);
  maxSum = Math.max(maxSum, current);
}

console.log(maxSum);",
  "language": "JAVASCRIPT"
}
